const createCounter = (start = 0) => {
  let count = start;
  return {
    increment() {
      count += 1;
      return count;
    },
    decrement() {
      count -= 1;
      return count;
    },
    getCount() {
      return count;
    }
  };
};
const counter = createCounter(5);
console.log(counter.increment(), counter.decrement(), counter.getCount());

class Animal {
  constructor(name) {
    this.name = name;
  }
  speak() {
    return `${this.name} makes a sound`;  
  }
}
class Dog extends Animal {
  speak() {
    return `${this.name} barks`;
  }
}
const dog = new Dog('Buddy');
console.log(dog.speak());

function validateUser(user) {
  if (!user.name) { throw new Error('Name required'); }
  if (user.age < 18) { throw new Error('Must be adult'); }
  return true;
}
try {
  validateUser({ age: 16 });
} catch (error) {
  console.log('Validation failed:', error.message);
}

const module = (() => {
  const privateCounter = 0;
  return {
    increment(value) {
      return privateCounter + value;
    }
  };
})();
console.log('module result', module.increment(3));

